"""Gate 1: artifact inventory with SHA-256 (read-only). Writes manuscript_ipm/records/artifact-inventory.md."""
import hashlib, json, subprocess
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
GROUPS = [
 ("Design / pre-registration", ["design/experiment_design_v0.2.md", "design/addendum_v0.2.1.md", "design/addendum_v0.2.2.md", "design/addendum_v0.2.3.md", "design/addendum_v0.2.4.md", "design/addendum_v0.3.md", "design/addendum_v0.3.1.md", "design/addendum_v0.3.2.md"], "pre-registered design and deviations"),
 ("Configs", ["configs/main.yaml", "configs/v03_hp_qwen.yaml", "configs/v03_hp_llama.yaml", "configs/v03_nq_qwen.yaml", "configs/v03_nq_llama.yaml", "configs/resolved_revisions.json"], "experiment configuration, pinned model revisions"),
 ("NQ data (v0.2)", ["paper_inputs/data/raw/nq_qrels/test.tsv", "paper_inputs/data/processed/nq_joined.jsonl", "paper_inputs/data/processed/nq_query_order.txt", "paper_inputs/data/processed/nq_join_stats.json"], "qrels, joined queries with answers, seeded order"),
 ("NQ retrieval runs (v0.2, top-10 copies)", sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/results/raw/top10").glob("*.jsonl")), "per-query ranked lists R0-R6 on the 300k sub-corpus"),
 ("Qwen-NQ answers (v0.2)", sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/results/processed/answers").glob("main__*.jsonl")), "scored answers incl. k ablation, A3 prompt, A2rep"),
 ("v0.2 statistics", ["paper_inputs/results/statistics/rq12_main.json", "paper_inputs/results/statistics/rq34_main.json", "paper_inputs/results/raw/throughput_v02_S1.jsonl"], "v0.2 statistics and cost records"),
 ("Judge (v0.2) + human labels", sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/results/raw/judgements").glob("*.jsonl")) + ["annotation/sample_v1_blind.json", "annotation/sample_v1_key.json", "annotation/judge_validation_labels.json"], "LLM-judge verdicts, 200-item sample, author labels"),
 ("HotpotQA (v0.3 S1/S2)", ["paper_inputs/v03_hp/data/hp_joined.jsonl", "paper_inputs/v03_hp/data/hp_query_order.txt", "paper_inputs/v03_hp/processed/hp_join_stats.json", "paper_inputs/v03_hp/summary/v03_hp_retrieval_summary.json", "paper_inputs/v03_hp/raw/download.jsonl", "paper_inputs/v03_hp/raw/encode.jsonl", "paper_inputs/v03_hp/raw/subcorpus.jsonl", "paper_inputs/v03_hp/raw/generation_runs.jsonl", "paper_inputs/v03_hp/raw/env_v03_S1hp.json", "paper_inputs/v03_hp/raw/env_v03_S2hp.json"] + sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/v03_hp/processed/answers").glob("*.jsonl")), "HotpotQA join, retrieval summary, Qwen+Llama answers"),
 ("NQ v0.3 S3 (Llama, top-k)", ["paper_inputs/v03_nq/raw/generation_runs.jsonl", "paper_inputs/v03_nq/raw/env_v03_S3nq.json"] + sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/v03_nq/processed/answers").glob("*.jsonl")), "Llama-NQ answers, E4 top-k answers"),
 ("NQ v0.3 S4 (E5,E6,E7,E9,E12)", ["paper_inputs/v03_nq_s4/raw/rerank.jsonl", "paper_inputs/v03_nq_s4/raw/hnsw.jsonl", "paper_inputs/v03_nq_s4/raw/mechanism.jsonl", "paper_inputs/v03_nq_s4/raw/throughput.jsonl", "paper_inputs/v03_nq_s4/raw/bm25.jsonl", "paper_inputs/v03_nq_s4/raw/encode.jsonl", "paper_inputs/v03_nq_s4/raw/search.jsonl", "paper_inputs/v03_nq_s4/raw/env_v03_S4nq.json", "paper_inputs/v03_nq_s4/summary/v03_nq_full_summary.json", "paper_inputs/v03_nq_s4/summary/v03_nq_main_summary.json"] + sorted(str(p.relative_to(ROOT)) for p in (ROOT/"paper_inputs/v03_nq_s4/processed/answers").glob("*.jsonl")), "reranker, HNSW, mechanism, cost repeats, full corpus"),
 ("Analysis code", ["src/analysis/stats.py", "src/analysis/v03_analysis.py", "src/analysis/judge_agreement.py", "src/common/ir_metrics.py", "src/evaluation/answer.py", "src/generation/prompts.py"], "statistics, metrics, scoring, prompts"),
 ("Analysis outputs", ["paper_outputs/v03/statistics/v03_analysis.json", "paper_outputs/v03/statistics/judge_agreement.json"], "all statistics used in the manuscript"),
 ("Figure/table code", ["paper_figures/make_figures_v03.py", "paper_figures/make_tables_v03.py"], "figures and LaTeX tables from v03_analysis.json"),
]
def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()[:16]
commit = subprocess.run(["git", "-C", str(ROOT), "rev-parse", "--short", "HEAD"], capture_output=True, text=True).stdout.strip()
rows = []
for g, files, purpose in GROUPS:
    for f in files:
        p = ROOT / f
        ok = p.exists()
        n = sum(1 for _ in open(p, encoding="utf-8", errors="replace")) if ok and p.suffix in (".jsonl", ".txt", ".tsv") else ""
        rows.append(f"| {f} | {p.suffix[1:]} | {g}: {purpose} | git {commit} | {'yes (parsed by analysis; see audit)' if ok else 'MISSING'} | {sha(p) if ok else ''} | {'present' if ok else 'MISSING'} | {f'{n} lines' if n != '' else ''} |")
hdr = "# Artifact inventory (Gate 1)\n\nGenerated by manuscript_ipm/tools/inventory.py at repository commit " + commit + ". Hash = first 16 hex of SHA-256. Files are read-only inputs; no artifact was modified.\n\n| Relative path | Type | Purpose | Provenance/version | Content inspected? | Hash | Validation status | Notes |\n|---|---|---|---|---|---|---|---|\n"
(ROOT / "manuscript_ipm/records/artifact-inventory.md").write_text(hdr + "\n".join(rows) + "\n")
print(len(rows), "rows;", sum("MISSING" in r for r in rows), "missing")
